#include "flex_delta_quantization_candidate.h"
#include <fstream>
#include <iostream>
int main(){try{std::ifstream file(R"(D:\SteamLibrary\steamapps\common\SourceFilmmaker\game\usermod\models\anno\mamagen\mamagen.mdl)",std::ios::binary);if(!file)throw std::runtime_error("model missing");std::vector<uint8_t>bytes((std::istreambuf_iterator<char>(file)),{});float scale=readMdlFlexFixedScaleCandidate(bytes);std::ofstream out("outputs/sfm64-flex-quantization.bin",std::ios::binary);out.write(reinterpret_cast<const char*>(&scale),4);for(uint32_t word=0;word<65536;++word){uint32_t bits=UINT32_MAX;try{float restored=float(quantizeFlexDeltaCandidate(finiteFlexHalfCandidate(uint16_t(word)),scale))*scale;std::memcpy(&bits,&restored,4);}catch(const std::runtime_error&){}out.write(reinterpret_cast<const char*>(&bits),4);}if(!out)throw std::runtime_error("quantization output failed");if(quantizeFlexDeltaCandidate(-1.9f,1)!=-1||quantizeFlexDeltaCandidate(32767.5f,1)!=32767||quantizeFlexDeltaCandidate(-32768.5f,1)!=-32768)throw std::runtime_error("truncation mismatch");for(float bad:{0.0f,-1.0f}){bool rejected=false;try{quantizeFlexDeltaCandidate(1,bad);}catch(const std::runtime_error&){rejected=true;}if(!rejected)throw std::runtime_error("invalid scale accepted");}std::cout<<"quantization candidate exhaustive output written, truncation and invalid scale passed\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
